package com.alpharip.staffmod.AuditFindingsBoard; public final class AuditFindingNote { private final String author,text;private final long createdAt;public AuditFindingNote(String a,String t,long at){if(t==null||t.trim().isEmpty())throw new IllegalArgumentException("Note text is required");author=a==null?"":a.trim();text=t.trim();createdAt=Math.max(0L,at);}public String getAuthor(){return author;}public String getText(){return text;}public long getCreatedAt(){return createdAt;} }
